/** A set of permissions that is granted together, and that may inherit those of other roles */
export interface AccessRoleRow {
  /** What identifies the role, made by the application */
  readonly roleId: string;
  /** The role's short name, unique within its tenant */
  readonly roleKey: string;
  /** What the role is called */
  readonly name: string;
  /** Whether the platform or a tenant made it */
  readonly kind: "system" | "custom";
  /** What a holder of the role does */
  readonly definition: string;
  /** Whether it is a role that an agent may never hold, and that needs a time-boxed grant where privileged access is composed */
  readonly isPrivileged: boolean;
  /** Whether the role is in use */
  readonly status: "active" | "retired";
  /** The tenant that made the role; empty for a role of the platform, usable in every tenant */
  readonly tenantId: string | null;
}

