/** A role granted to a principal of any kind, in a tenant, perhaps for one resource and for a time */
export interface RoleAssignmentRow {
  /** What identifies the grant, made by the application */
  readonly roleAssignmentId: string;
  /** The kind of the one resource the grant is limited to, where it is */
  readonly resourceType: string | null;
  /** The one resource the grant is limited to, where it is */
  readonly resourceId: string | null;
  /** When the grant starts */
  readonly validFrom: Timestamp;
  /** When the grant ends, where it does */
  readonly validTo: Timestamp | null;
  /** Why it was granted */
  readonly reason: string | null;
  /** Where the grant is */
  readonly status: "active" | "revoked" | "expired";
  /** When it was ended early */
  readonly revokedAt: Timestamp | null;
  /** How it came to be */
  readonly via: "direct" | "privileged_grant" | "directory" | "invitation";
  /** A hash of the principal, the role, the tenant and the resource, unique, so that a grant is not made twice where the resource is empty */
  readonly assignmentKey: string;
  /** Who holds the role */
  readonly principalId: string;
  /** The role */
  readonly roleAccessRoleRoleId: string;
  /** The tenant the grant is in */
  readonly tenantId: string;
  /** Who granted it */
  readonly grantedByPrincipalId: string;
}

/** What an insert into role_assignment takes: what the database fills may be left out. */
export interface RoleAssignmentInsert {
  readonly roleAssignmentId: string;
  readonly resourceType?: string | null;
  readonly resourceId?: string | null;
  readonly validFrom: Timestamp;
  readonly validTo?: Timestamp | null;
  readonly reason?: string | null;
  readonly status: "active" | "revoked" | "expired";
  readonly revokedAt?: Timestamp | null;
  readonly via: "direct" | "privileged_grant" | "directory" | "invitation";
  readonly assignmentKey: string;
  readonly principalId: string;
  readonly roleAccessRoleRoleId: string;
  readonly tenantId: string;
  readonly grantedByPrincipalId: string;
}

/** The key of a row of role_assignment. */
export type RoleAssignmentKey = { readonly roleAssignmentId: string };

/** A role granted to a principal of any kind, in a tenant, perhaps for one resource and for a time */
export const roleAssignment = defineTable<RoleAssignmentRow, RoleAssignmentInsert, "roleAssignment">({
  alias: "roleAssignment",
  name: "role_assignment",
  columns: {
    roleAssignmentId: "role_assignment_id",
    resourceType: "resource_type",
    resourceId: "resource_id",
    validFrom: "valid_from",
    validTo: "valid_to",
    reason: "reason",
    status: "status",
    revokedAt: "revoked_at",
    via: "via",
    assignmentKey: "assignment_key",
    principalId: "principal_id",
    roleAccessRoleRoleId: "role_access_role_role_id",
    tenantId: "tenant_id",
    grantedByPrincipalId: "granted_by_principal_id",
  },
  primaryKey: ["roleAssignmentId"],
  foreignKeys: [
    { columns: ["principalId"], references: "principal", referencesColumns: ["principalId"] },
    { columns: ["roleAccessRoleRoleId"], references: "accessRole", referencesColumns: ["roleId"] },
    { columns: ["tenantId"], references: "tenant", referencesColumns: ["tenantId"] },
    { columns: ["grantedByPrincipalId"], references: "principal", referencesColumns: ["principalId"] },
  ],
});

